values.content:
Generate release notes.

Product: {{ $json.productName || 'the product' }}
Version: {{ $json.version }}
Release date: {{ $json.releaseDate }}
Tone: {{ $json.tone.replace(/_/g,' ') }}
Output format: {{ $json.outputFormat }}

Changes ({{ $json.changes.length }} total):
{{ $json.changes.filter(c=>!c.internal).map(c=>c.id+' ['+c.type+']'+(c.audience!=='all'?' ('+c.audience+')':'')+': '+c.title+(c.description?' — '+c.description:'')).join('\n') }}

{{ $json.includeInternalNotes && $json.changes.some(c=>c.internal) ? 'Internal only (not public):\n' + $json.changes.filter(c=>c.internal).map(c=>c.id+': '+c.title).join('\n') : '' }}

Return JSON:
{"release_headline":"1-sentence summary of the most important thing in this release","user_facing_notes":{"header":"friendly header for the release","summary":"2-3 sentence non-technical summary of what's new and why it matters to users","sections":[{"type":"new_features|improvements|bug_fixes|important_notes","items":[{"title":"benefit-led title","description":"1-2 sentences in plain language"}]}]},"technical_notes":{"summary":"technical summary for developers","breaking_changes":[{"change":"","migration_notes":""}],"sections":[{"type":"","items":[{"title":"","description":"","ticket":""}]}]},"changelog_markdown":"complete markdown changelog entry ready to paste into CHANGELOG.md","email_subject":"release announcement email subject line","tweet_announcement":"under 280 chars, announces the release"}
